  capTop:        { display:'flex', alignItems:'center', gap:8, marginBottom:4 },
  capCheck:      { width:15, height:15, borderRadius:4, border:'1.5px solid rgba(255,255,255,0.18)', display:'flex', alignItems:'center', justifyContent:'center', flexShrink:0 },
  capCheckActive:{ background:'#00d4aa', borderColor:'#00d4aa' },
  capType:       { fontSize:12, color:'#e8eaf0', fontWeight:500, flex:1 },
  capUnit:       { fontSize:10, color:'#4a5260' },
  capSeuil:      { fontSize:10, color:'#4a5260' },
  relaisInfo:    { display:'flex', alignItems:'center', gap:8, padding:'10px 14px', background:'rgba(0,212,170,0.06)', border:'1px solid rgba(0,212,170,0.15)', borderRadius:7, fontSize:12, color:'#00d4aa', marginBottom:16 },
}
